CREATE TABLE IF NOT EXISTS gis_phase358_geometry_version (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), source_a TEXT NOT NULL, source_b TEXT NOT NULL, feature_id TEXT NOT NULL, state_match BOOLEAN NOT NULL DEFAULT false, centroid_distance DOUBLE PRECISION, area_ratio DOUBLE PRECISION, extent_shift DOUBLE PRECISION, version_class TEXT NOT NULL, confidence DOUBLE PRECISION NOT NULL DEFAULT 0, evidence JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(source_a,source_b,feature_id));